tool_input.content:
[
  {
    "name": "generate_code_docs",
    "description": "Analyze code and create technical documentation",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "The path to the code file or directory to analyze"
        },
        "output_dir": {
          "type": "string",
          "description": "The output directory for documentation (default: ./docs/code)"
        },
        "format": {
          "type": "string",
          "description": "The format for documentation (markdown|json)",
          "enum": ["markdown", "json"],
          "default": "markdown"
        },
        "depth": {
          "type": "string",
          "description": "The analysis depth (shallow|deep)",
          "enum": ["shallow", "deep"],
          "default": "deep"
        }
      },
      "required": [
        "path"
      ]
    },
    "agent": true
  },
  {
    "name": "generate_lore",
    "description": "Chronicle system evolution and philosophy",
    "parameters": {
      "type": "object",
      "properties": {
        "topic": {
          "type": "string",
          "description": "The topic or system to chronicle"
        },
        "type": {
          "type": "string",
          "description": "The type of lore (evolution|philosophy|decision|architecture)",
          "enum": ["evolution", "philosophy", "decision", "architecture"],
          "default": "evolution"
        },
        "project": {
          "type": "string",
          "description": "The basic-memory project to store lore",
          "default": "skogai"
        }
      },
      "required": [
        "topic"
      ]
    },
    "agent": true
  },
  {
    "name": "index_memory",
    "description": "Update memory system indices",
    "parameters": {
      "type": "object",
      "properties": {
        "project": {
          "type": "string",
          "description": "The basic-memory project",
          "default": "skogai"
        },
        "type": {
          "type": "string",
          "description": "The index type to update (knowledge|lore|all)",
          "enum": ["knowledge", "lore", "all"],
          "default": "all"
        }
      },
      "required": []
    },
    "agent": true
  },
  {
    "name": "review_docs",
    "description": "Analyze existing documentation quality",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "The path to documentation to review"
        },
        "output": {
          "type": "string",
          "description": "The output file for review results"
        },
        "format": {
          "type": "string",
          "description": "The output format (markdown|json)",
          "enum": ["markdown", "json"],
          "default": "markdown"
        }
      },
      "required": [
        "path"
      ]
    },
    "agent": true
  },
  {
    "name": "fs_mkdir",
    "description": "Create a new directory at the specified path.",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "The path of the directory to create"
        }
      },
      "required": [
        "path"
      ]
    }
  },
  {
    "name": "fs_write",
    "description": "Write the full file contents to a file at the specified path.",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "The path of the file to write to"
        },
        "contents": {
          "type": "string",
          "description": "The full contents to write to the file"
        }
      },
      "required": [
        "path",
        "contents"
      ]
    }
  },
  {
    "name": "fs_rm",
    "description": "Remove the file or directory at the specified path.",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "The path of the file or directory to remove"
        }
      },
      "required": [
        "path"
      ]
    }
  },
  {
    "name": "fs_ls",
    "description": "List all files and directories at the specified path.",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "The path of the directory to list"
        }
      },
      "required": [
        "path"
      ]
    }
  },
  {
    "name": "fs_patch",
    "description": "Apply a patch to a file at the specified path.\nThis can be used to edit the file, without having to rewrite the whole file.",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "The path of the file to apply to"
        },
        "contents": {
          "type": "string",
          "description": "The patch to apply to the file\n\nHere is an example of a patch block that can be applied to modify the file to request the user's name:\n--- a/hello.py\n+++ b/hello.py\n@@ ... @@\n def hello():\n-    print(\"Hello World\")\n+    name = input(\"What is your name? \")\n+    print(f\"Hello {name}\")"
        }
      },
      "required": [
        "path",
        "contents"
      ]
    }
  },
  {
    "name": "fs_cat",
    "description": "Read the contents of a file at the specified path.\nUse this when you need to examine the contents of an existing file.",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "The path of the file to read"
        }
      },
      "required": [
        "path"
      ]
    }
  },
  {
    "name": "execute_command",
    "description": "Execute the shell command.",
    "parameters": {
      "type": "object",
      "properties": {
        "command": {
          "type": "string",
          "description": "The command to execute."
        }
      },
      "required": [
        "command"
      ]
    }
  }
]
